// === Kontakt-Vorfilter · Honeypot, Zeitfalle, Drosselung ===
// Alle Stellschrauben stehen hier oben.
const MIN_MS        = 2500;  // schneller als das = Bot
const MAX_PRO_IP    = 3;     // Anfragen je IP im Fenster
const FENSTER_MIN   = 60;    // Länge des Fensters in Minuten
const MAX_LINKS     = 2;     // erlaubte Links in der Nachricht
const MAX_NAME      = 100;
const MAX_NACHRICHT = 5000;

const sd      = $getWorkflowStaticData('global');
const jetzt   = Date.now();
const fenster = FENSTER_MIN * 60 * 1000;
const out     = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const h = item.json.headers || {};

  const ip = String(h['x-forwarded-for'] || h['x-real-ip'] || '')
    .split(',')[0].trim() || 'unbekannt';

  const name      = String(b.name || '').trim();
  const email     = String(b.email || '').trim();
  const nachricht = String(b.nachricht || '').trim();
  const falle     = String(b.website || '').trim();   // Honeypot-Feld
  const dauer     = Number(b.dauer) || 0;             // ms zwischen Laden und Absenden

  let grund = null;
  if (falle)                                   grund = 'Honeypot ausgefüllt';
  else if (dauer > 0 && dauer < MIN_MS)        grund = `Zu schnell (${dauer} ms)`;
  else if (!name || !email || !nachricht)      grund = 'Pflichtfeld fehlt';
  else if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(email)) grund = 'E-Mail unplausibel';
  else if (name.length > MAX_NAME || nachricht.length > MAX_NACHRICHT) grund = 'Feld zu lang';
  else if ((nachricht.match(/https?:\/\//gi) || []).length > MAX_LINKS) grund = 'Zu viele Links';

  // Drosselung je IP
  if (!grund && ip !== 'unbekannt') {
    const sp    = sd.kontaktIps || (sd.kontaktIps = {});
    const liste = (sp[ip] || []).filter(t => jetzt - t < fenster);
    if (liste.length >= MAX_PRO_IP) grund = `Drosselung: ${liste.length} in ${FENSTER_MIN} min`;
    else { liste.push(jetzt); sp[ip] = liste; }
  }

  // Merkliste alle 6 Stunden aufräumen
  if (sd.kontaktIps && jetzt - (sd.letzteReinigung || 0) > 6 * 3600 * 1000) {
    for (const k of Object.keys(sd.kontaktIps)) {
      const rest = sd.kontaktIps[k].filter(t => jetzt - t < fenster);
      if (rest.length) sd.kontaktIps[k] = rest; else delete sd.kontaktIps[k];
    }
    sd.letzteReinigung = jetzt;
  }

  if (grund) { console.log('Kontakt abgewiesen:', grund, '| IP', ip); continue; }

  out.push({ json: {
    name, email, nachricht,
    firma:   String(b.firma   || '').trim(),
    telefon: String(b.telefon || '').trim(),
    quelle:  b.quelle  || '',
    sprache: b.sprache || '',
    eingegangen: new Date(jetzt).toISOString()
  }});
}

return out;
